(() => {
  const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let data=null,filtered=[],page=0;const pageSize=12;
  const controls=['#data-split','#data-phase','#data-topology','#data-scenario','#data-search'];
  function applyFilters(){if(!data)return;const values=controls.map(s=>q(s).value.toLowerCase());filtered=data.rows.filter(r=>(!values[0]||r.split===values[0])&&(!values[1]||r.phase===values[1])&&(!values[2]||r.topology===values[2])&&(!values[3]||r.scenario===values[3])&&(!values[4]||(r.run_id+' '+r.seed).toLowerCase().includes(values[4])));page=0;renderRows();}
  function displayNumber(v){if(v===undefined||v===''||!Number.isFinite(Number(v)))return 'Missing';return Number(v).toFixed(4);}
  function renderRows(){const total=filtered.length,start=page*pageSize,view=filtered.slice(start,start+pageSize);q('#dataset-totals').innerHTML=`<span><strong>${total}</strong>observations</span><span><strong>${new Set(filtered.map(r=>r.run_id)).size}</strong>runs</span><span><strong>${filtered.filter(r=>r.label_synthetic_probe==='1').length}</strong>synthetic-probing intervals</span><span>of 216 original observations</span>`;q('#dataset-rows').innerHTML=view.length?view.map(r=>`<tr><td>${escape(r.run_id)}</td><td>${escape(r.split)}</td><td>${escape(r.scenario)}</td><td>${escape(r.phase)}</td><td>${escape(r.interval)}</td><td>${escape(r.label_synthetic_probe)}</td><td>${displayNumber(r.rtt_mean_ms)}</td><td>${displayNumber(r.measured_delivery_mbps)}</td></tr>`).join(''):'<tr><td colspan="8">No observations match these filters. Reset filters to see the full export.</td></tr>';q('#dataset-page').textContent=total?`${start+1}–${Math.min(start+pageSize,total)} of ${total} · page ${page+1} / ${Math.ceil(total/pageSize)}`:'0 matching observations';q('#data-prev').disabled=page===0;q('#data-next').disabled=start+pageSize>=total;q('#data-download').disabled=!total;}
  controls.forEach(s=>q(s).addEventListener(s==='#data-search'?'input':'change',applyFilters));
  q('#data-reset').addEventListener('click',()=>{controls.forEach(s=>q(s).value='');applyFilters();});
  q('#data-prev').addEventListener('click',()=>{if(page>0){page--;renderRows();}});q('#data-next').addEventListener('click',()=>{if((page+1)*pageSize<filtered.length){page++;renderRows();}});
  q('#data-download').addEventListener('click',()=>{if(!data||!filtered.length)return;const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv=[data.columns,...filtered.map(r=>data.columns.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`H14_filtered_${filtered.length}_observations.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  fetch('evidence/dataset.json').then(r=>{if(!r.ok)throw Error('Dataset unavailable');return r.json();}).then(d=>{data=d;q('#dataset-schema').textContent=d.columns.join(' · ')+'\n\nSHA-256: '+d.sha256;applyFilters();}).catch(()=>{q('#dataset-totals').textContent='The dataset explorer could not load. Download the original CSV below to inspect all observations.';q('#data-download').disabled=true;});
  let graphs=[],group='paper';const dialog=q('#graph-dialog');let previousFocus=null;
  function openGraph(g){previousFocus=document.activeElement;q('#graph-dialog-title').textContent=g.title;q('#graph-dialog-image').src=g.file;q('#graph-dialog-image').alt=g.title;q('#graph-dialog-scope').textContent=g.scope+' · Original supplied graph, shown in its original colors.';q('#graph-dialog-download').href=g.file;dialog.showModal();q('#graph-close').focus();}
  q('#graph-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>previousFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
  function renderGallery(){const shown=graphs.filter(g=>group==='all'||g.group===group);q('#gallery-status').textContent=`${shown.length} of ${graphs.length} supplied graphs · Select a graph to enlarge it.`;q('#graph-grid').innerHTML=shown.map((g,i)=>`<article class="graph-card"><button class="graph-open" data-open-graph="${i}" aria-label="Enlarge ${escape(g.title)}"><img src="${escape(g.file)}" alt="${escape(g.title)}" loading="lazy" decoding="async"></button><div class="graph-body"><span>${escape(g.scope)}</span><h3>${escape(g.title)}</h3><div class="graph-actions"><button data-open-graph="${i}">Enlarge ↗</button><a href="${escape(g.file)}" download>Original PNG ↓</a></div></div></article>`).join('');qa('[data-open-graph]').forEach(b=>b.addEventListener('click',()=>openGraph(shown[Number(b.dataset.openGraph)])));}
  qa('[data-graph-group]').forEach(b=>b.addEventListener('click',()=>{group=b.dataset.graphGroup;qa('[data-graph-group]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',active);});renderGallery();}));
  fetch('evidence/graphs.json').then(r=>{if(!r.ok)throw Error('Graphs unavailable');return r.json();}).then(g=>{graphs=g;qa('[data-graph-group]').forEach(b=>{const n=b.dataset.graphGroup==='all'?graphs.length:graphs.filter(x=>x.group===b.dataset.graphGroup).length;b.textContent=b.textContent.replace(/\d+$/,n);});renderGallery();}).catch(()=>q('#gallery-status').textContent='The graph gallery could not load. All original figures remain available in the guide package download.');
})();
